    const yaw = Math.atan2(2 * (w * z + x * y), 1 - 2 * (y * y + z * z));
    const c = Math.cos(yaw), sn = Math.sin(yaw);
    const wvx = s.qvel[0] as number, wvy = s.qvel[1] as number;
    const bvx = c * wvx + sn * wvy;
    const bvy = -sn * wvx + c * wvy;
    // Step into the push: command extra velocity along the excess pelvis velocity.
    const K = REFLEX_GAIN, DEAD = REFLEX_DEADBAND;
    const ex = bvx - bx, ey = bvy - by;
    const gx = Math.abs(ex) > DEAD ? ex - Math.sign(ex) * DEAD : 0;
    const gy = Math.abs(ey) > DEAD ? ey - Math.sign(ey) * DEAD : 0;
    const lim = REFLEX_LIMITS.v;
    out[0] = Math.max(-lim, Math.min(lim, bx + K * gx));
    out[1] = Math.max(-lim, Math.min(lim, by + K * gy));
    out[2] = base[2] as number;
  }
}

/** Reflex gain (ratio) and deadband (m/s). */
const REFLEX_GAIN = 1.5;
const REFLEX_DEADBAND = 0.1;

/** Command limits the Walker applies after the reflex. */
export const REFLEX_LIMITS = { v: 1.0, yaw: 1.0 } as const;
